    "category": "Economia",
    "ingestedAt": "30/10/2026 às 14:15",
    "imageUrl": "https://imagens.ebc.com.br/Bvwe_csVVdE39DW5hshc04H6tII=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/10/30/_int2625.jpg?itok=lV5JXMX2",
